// Expects msg.payload = {device, ts, laneA, laneB, ped}
// Normalize ADC readings (0..4095) into 0..1 demand scores.

const p = msg.payload || {};
const laneA = Number(p.laneA ?? 0);
const laneB = Number(p.laneB ?? 0);
const ped   = Number(p.ped ?? 0);

function clamp01(x){ return Math.max(0, Math.min(1, x)); }

// Simple normalization: assume useful range 200..3500
function norm(v){
  const lo = 200, hi = 3500;
  return clamp01((v - lo) / (hi - lo));
}

const demandA = norm(laneA);
const demandB = norm(laneB);

let twin = flow.get('twin') || {};

// Edge-detect ped press
const pedNow = (ped === 1);
const pedPrev = !!twin.pedPrev;
const pedRising = pedNow && !pedPrev;

// Rolling averages
const alpha = 0.2;
twin.avgA = (twin.avgA == null) ? demandA : (alpha*demandA + (1-alpha)*twin.avgA);
twin.avgB = (twin.avgB == null) ? demandB : (alpha*demandB + (1-alpha)*twin.avgB);

twin.last = {
  ts: p.ts || Math.floor(Date.now()/1000),
  laneA, laneB,
  demandA, demandB,
  ped: pedNow
};

twin.pedPrev = pedNow;

// Latch a pedestrian request until served
if (pedRising) {
  twin.pedLatched = true;
  twin.pedRequestedAt = Date.now();
}

flow.set('twin', twin);

// Send debug-friendly payload
msg.payload = { demandA, demandB, avgA: twin.avgA, avgB: twin.avgB, pedLatched: !!twin.pedLatched };
return msg;

let policy = flow.get('policy') || {eco:false, ped_priority:false, max_green_ms:15000};
if (msg.topic === 'eco') policy.eco = !!msg.payload;
if (msg.topic === 'ped_priority') policy.ped_priority = !!msg.payload;
// keep a safe bound
policy.max_green_ms = 15000;
flow.set('policy', policy);
msg.payload = JSON.stringify(policy);
return msg;

// Runs every 1s. Uses flow.twin (latest telemetry + state) and flow.policy (toggles).
// Publishes deterministic phase commands when a phase expires.

const now = Date.now();
let twin = flow.get('twin') || {};
let policy = flow.get('policy') || {eco:false, ped_priority:false, max_green_ms:15000};

if (!twin.last) return null; // no telemetry yet

// Initialize state if missing
if (!twin.phase) {
  twin.phase = 'A_GREEN';
  twin.phaseEndsAt = now + 8000;
  twin.reason = 'Init: start with A_GREEN';
  flow.set('twin', twin);
  return [ {payload: buildCmd(twin.phase, 8000, twin.reason, policy)},
           {payload: JSON.stringify(policy)},
           {payload: twin.phase},
           {payload: twin.reason} ];
}

// If current phase still active, just update status outputs
if (now < (twin.phaseEndsAt || 0)) {
  return [ null,
           {payload: JSON.stringify(policy)},
           {payload: twin.phase},
           {payload: twin.reason} ];
}

// Phase expired: compute next phase
const avgA = Number(twin.avgA ?? twin.last.demandA ?? 0);
const avgB = Number(twin.avgB ?? twin.last.demandB ?? 0);
const pedLatched = !!twin.pedLatched;

// Safety timings
const YELLOW_MS = 2000;
const ALL_RED_MS = 500;
const PED_MS = 6000;

function greenDuration(phase){
  const baseMin = 6000;
  const baseMax = policy.eco ? policy.max_green_ms : 20000;
  const d = (phase === 'A_GREEN') ? avgA : avgB;
  const ms = Math.round(baseMin + d * (baseMax - baseMin));
  return Math.max(baseMin, Math.min(baseMax, ms));
}

function chooseTargetGreen(){
  if (pedLatched && policy.ped_priority) return 'PED_CROSS';
  let scoreA = avgA;
  let scoreB = avgB;
  if (policy.eco) {
    if (twin.phase.includes('A_')) scoreA += 0.08;
    if (twin.phase.includes('B_')) scoreB += 0.08;
  }
  return (scoreA >= scoreB) ? 'A_GREEN' : 'B_GREEN';
}

function nextPhaseSequence(target){
  const cur = twin.phase;

  // After yellow -> all red
  if (cur === 'A_YELLOW' || cur === 'B_YELLOW') return {phase:'ALL_RED', dur:ALL_RED_MS};

  // After all red -> target
  if (cur === 'ALL_RED') return {phase: target, dur: (target==='PED_CROSS')?PED_MS:greenDuration(target)};

  // After ped -> all red
  if (cur === 'PED_CROSS') return {phase:'ALL_RED', dur:ALL_RED_MS};

  // From A_GREEN to B_GREEN
  if (cur === 'A_GREEN' && target === 'B_GREEN') return {phase:'A_YELLOW', dur:YELLOW_MS};
  if (cur === 'B_GREEN' && target === 'A_GREEN') return {phase:'B_YELLOW', dur:YELLOW_MS};

  // Stay on same green (extend)
  if (cur === target) return {phase: target, dur: greenDuration(target)};

  // If target is PED_CROSS from a green, go yellow first then ped (via all-red next tick)
  if (target === 'PED_CROSS') {
    if (cur === 'A_GREEN') return {phase:'A_YELLOW', dur:YELLOW_MS};
    if (cur === 'B_GREEN') return {phase:'B_YELLOW', dur:YELLOW_MS};
  }

  // fallback
  return {phase:'ALL_RED', dur:ALL_RED_MS};
}

function buildReason(nextPhase){
  return `avgA=${avgA.toFixed(2)} | avgB=${avgB.toFixed(2)} | ped=${pedLatched?'YES':'NO'} | eco=${policy.eco} | ped_priority=${policy.ped_priority} | next=${nextPhase}`;
}

function buildCmd(phase, duration, reason, policyObj){
  return {
    phase,
    duration_ms: duration,
    reason,
    policy: {
      eco: !!policyObj.eco,
      ped_priority: !!policyObj.ped_priority,
      max_green_ms: Number(policyObj.max_green_ms || 15000)
    }
  };
}

const target = chooseTargetGreen();
const seq = nextPhaseSequence(target);

// If we are going to serve ped now, clear the latch
if (seq.phase === 'PED_CROSS') {
  twin.pedLatched = false;
  twin.lastPedWaitMs = twin.pedRequestedAt ? (now - twin.pedRequestedAt) : null;
}

const reason = buildReason(seq.phase);

// Update state
twin.phase = seq.phase;
twin.phaseEndsAt = now + seq.dur;
twin.reason = reason;
flow.set('twin', twin);

return [ {payload: buildCmd(twin.phase, seq.dur, reason, policy)},
         {payload: JSON.stringify(policy)},
         {payload: twin.phase},
         {payload: twin.reason} ];
